"use client";

import { forwardRef, type ComponentProps } from "react";
import LegacySidebarNav from "../beautiful-ui/primitives/SidebarNav";
import { BeautifulUIRoot } from "../beautiful-ui/BeautifulUIRoot";

export type SidebarNavProps = NonNullable<ComponentProps<typeof LegacySidebarNav>>;

export const SidebarNav = forwardRef<HTMLDivElement, SidebarNavProps>((props, ref) => (
  <BeautifulUIRoot ref={ref}>
    <LegacySidebarNav {...props} />
  </BeautifulUIRoot>
));

SidebarNav.displayName = "SidebarNav";

export default SidebarNav;

"use client";

import "../beautiful-ui.css";

import {
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";
import { createPortal } from "react-dom";
import { ArrowLeftToLine as IconArrowBoxLeft, Popsicle as IconPopsicle2 } from "lucide-react";
import { useIcon, type IconName } from "@/lib/icon-context";
import { useShape } from "@/lib/shape-context";
import { BeautifulUIPortalRoot } from "../BeautifulUIRoot";
import { useReducedMotion } from "../hooks/useReducedMotion";
import GlideMenu from "./GlideMenu";

/* ─────────────────────────────────────────────────────────
 * SIDEBAR NAV
 * Shared by the design-system preview and the harness shell:
 * compact workspace switcher, primary navigation, searchable
 * chat history, and a collapse that preserves icon alignment.
 * ───────────────────────────────────────────────────────── */

const WORKSPACE = { key: "creamery", name: "Creamery Ops", monogram: "C" };

const NAV_ITEMS: { key: string; label: string; icon: IconName; count?: string }[] = [
  { key: "home", label: "Home", icon: "home" },
  { key: "invite", label: "Invite users", icon: "users", count: "3/10" },
];

export type SidebarRecent = {
  id: string;
  label: string;
  prompt?: string;
};

const DEFAULT_RECENTS: SidebarRecent[] = [
  { id: "suppliers", label: "Supplier records" },
  { id: "todos", label: "Urgent to-dos this morning" },
  { id: "flavor", label: "Flavor page ticket" },
  { id: "workload", label: "Workload summary" },
  { id: "offboarding", label: "Off-board a supplier" },
  { id: "restock", label: "Batch restock function" },
  { id: "edits", label: "Propose flavor edits" },
  { id: "subway", label: "Subway surfing" },
];

type SidebarNavProps = {
  activeTitle?: string | null;
  className?: string;
  fill?: boolean;
  onNewChat?: () => void;
  onPick?: (id: string, label: string, prompt?: string) => void;
  /** controlled primary-nav selection (e.g. "home" | "invite") */
  activeNav?: string;
  onNavigate?: (key: string) => void;
  /** footer call-to-action — defaults to the demo "Upgrade" button */
  footerLabel?: string;
  footerIcon?: ReactNode;
  onFooterClick?: () => void;
  recents?: SidebarRecent[];
  variant?: string;
};

const SIDEBAR_MOTION = {
  expandedWidth: "clamp(208px, 22vw, 224px)",
  collapsedWidth: 52,
  duration: 240,
  copyDuration: 160,
  copyOffset: 8,
  easing: "cubic-bezier(0.16, 1, 0.3, 1)",
};

/* ─────────────────────────────────────────────────────────
 * CHAT SEARCH STORYBOARD
 *
 *   0ms   search is triggered; Chats label begins fading
 *   0ms   field grows right → left from the search control
 * 160ms   field fills the row; cursor is focused and ready
 * ───────────────────────────────────────────────────────── */
const CHAT_SEARCH_MOTION = {
  duration: 160,
  easing: "cubic-bezier(0.16, 1, 0.3, 1)",
};

function GlideGroup({ children }: { children: ReactNode }) {
  const shape = useShape();
  return (
    <GlideMenu
      rowSelector="[data-row]"
      highlightClassName={`sidebar-glide-highlight ${shape.item} bg-[var(--hover-2)]`}
      className="group/glide flex flex-col gap-px"
    >
      {children}
    </GlideMenu>
  );
}

function RailButton({
  icon,
  label,
  active = false,
  count,
  onClick,
  collapsed,
}: {
  icon: ReactNode;
  label: string;
  active?: boolean;
  count?: string;
  onClick?: () => void;
  collapsed: boolean;
}) {
  const shape = useShape();
  return (
    <button
      data-row
      type="button"
      aria-current={active ? "page" : undefined}
      onClick={onClick}
      style={{ width: collapsed ? 36 : "calc(var(--sidebar-expanded-width) - 16px)" }}
      className={`sidebar-row relative z-10 mx-2 flex h-8 items-center ${shape.item} px-2 text-left
        transition-[width,background-color,color,transform] duration-80 active:scale-[0.98]
        ${active ? "bg-[var(--hover-2)] group-hover/glide:bg-transparent group-focus-within/glide:bg-transparent" : ""}`}
    >
      <span
        className={`flex size-5 shrink-0 items-center justify-center ${active ? "text-[var(--ink)]" : "text-[var(--ink-2)]"}`}
      >
        {icon}
      </span>
      <span
        className={`sidebar-copy ml-1.5 min-w-0 flex-1 truncate text-[14px] font-medium ${active ? "text-[var(--ink)]" : "text-[var(--ink-2)]"}`}
      >
        {label}
      </span>
      {count && (
        <span className="sidebar-copy mr-2 shrink-0 text-[12px] font-medium tabular-nums text-[var(--ink-3)]">
          {count}
        </span>
      )}
    </button>
  );
}

function WorkspaceMenu({
  id,
  position,
  onClose,
}: {
  id: string;
  position: { top: number; left: number };
  onClose: (restoreFocus?: boolean) => void;
}) {
  const shape = useShape();
  const reducedMotion = useReducedMotion();
  const menuRef = useRef<HTMLDivElement>(null);
  const CheckIcon = useIcon("check");
  const PlusIcon = useIcon("plus");
  const SettingsIcon = useIcon("settings");
  const UsersIcon = useIcon("users");

  useEffect(() => {
    menuRef.current?.querySelector<HTMLElement>("[role='menuitem']")?.focus();
  }, []);

  const actions = [
    { label: "New workspace", icon: <PlusIcon size={16} /> },
    { label: "Workspace settings", icon: <SettingsIcon size={16} /> },
    { label: "Invite team members", icon: <UsersIcon size={16} /> },
  ];

  return createPortal(
    <BeautifulUIPortalRoot
      ref={menuRef}
      id={id}
      data-workspace-menu
      className={`fixed z-50 w-[min(16rem,calc(100vw-1.5rem))] ${shape.container} bg-[var(--surface)] p-1 text-[var(--ink)] shadow-[var(--shadow-overlay)]`}
      style={{
        top: position.top,
        left: position.left,
        animation: reducedMotion ? "none" : "pop-in 160ms cubic-bezier(0.23,1,0.32,1) both",
        transformOrigin: "top left",
      }}
      onKeyDown={(event) => {
        if (event.key !== "Escape") return;
        event.preventDefault();
        onClose(true);
      }}
      onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget)) onClose(false);
      }}
    >
      <GlideMenu
        role="menu"
        ariaLabel="Workspace menu"
        className="flex flex-col gap-px"
        highlightClassName={`inset-x-0 ${shape.item} bg-[var(--hover-2)]`}
      >
        <button
          data-menu-row
          type="button"
          role="menuitem"
          onClick={() => onClose(true)}
          className={`relative z-10 flex h-10 w-full items-center gap-1.5 ${shape.item} px-2 text-left transition-transform duration-80 active:scale-[0.98]`}
        >
          <span
            className={`flex size-6 shrink-0 items-center justify-center ${shape.item} bg-[var(--ink)] text-[11px] font-semibold text-[var(--surface)]`}
          >
            {WORKSPACE.monogram}
          </span>
          <span className="min-w-0 flex-1 truncate text-[13px] font-medium text-[var(--ink)]">
            {WORKSPACE.name}
          </span>
          <span className="shrink-0 text-[var(--ink)]">
            <CheckIcon size={18} />
          </span>
        </button>
        <div role="separator" className="my-1 h-px bg-[var(--line)]" />
        {actions.map((item) => (
          <button
            key={item.label}
            data-menu-row
            type="button"
            role="menuitem"
            tabIndex={-1}
            onClick={() => onClose(true)}
            className={`relative z-10 flex h-9 w-full items-center gap-1.5 ${shape.item} px-2 text-left transition-transform duration-80 active:scale-[0.98]`}
          >
            <span className="flex size-5 shrink-0 items-center justify-center text-[var(--ink-2)]">
              {item.icon}
            </span>
            <span className="min-w-0 flex-1 truncate text-[13px] text-[var(--ink)]">
              {item.label}
            </span>
          </button>
        ))}
        <div role="separator" className="my-1 h-px bg-[var(--line)]" />
        <button
          data-menu-row
          type="button"
          role="menuitem"
          tabIndex={-1}
          onClick={() => onClose(true)}
          className={`relative z-10 flex h-9 w-full items-center gap-1.5 ${shape.item} px-2 text-left transition-transform duration-80 active:scale-[0.98]`}
        >
          <span className="flex size-5 shrink-0 items-center justify-center text-[var(--ink-2)]">
            <IconArrowBoxLeft size={16} />
          </span>
          <span className="min-w-0 flex-1 truncate text-[13px] text-[var(--ink)]">Sign out</span>
        </button>
      </GlideMenu>
    </BeautifulUIPortalRoot>,
    document.body,
  );
}

export default function SidebarNav({
  activeTitle,
  className = "",
  fill = false,
  onNewChat,
  onPick,
  activeNav,
  onNavigate,
  footerLabel = "Upgrade",
  footerIcon,
  onFooterClick,
  recents = DEFAULT_RECENTS,
}: SidebarNavProps) {
  const shape = useShape();
  const reducedMotion = useReducedMotion();
  const HomeIcon = useIcon("home");
  const UsersIcon = useIcon("users");
  const PencilIcon = useIcon("pencil");
  const ChevronDownIcon = useIcon("chevron-down");
  const SearchIcon = useIcon("search");
  const CrossIcon = useIcon("x");
  const ArrowLeftIcon = useIcon("arrow-left");
  const [collapsed, setCollapsed] = useState(false);
  const [internalNav, setInternalNav] = useState("chats");
  const currentNav = activeNav ?? internalNav;
  const selectNav = (key: string) => {
    setInternalNav(key);
    onNavigate?.(key);
  };
  const [demoActiveTitle, setDemoActiveTitle] = useState<string | null>(null);
  const [workspaceOpen, setWorkspaceOpen] = useState(false);
  const [workspacePosition, setWorkspacePosition] = useState({ top: 0, left: 0 });
  const [searchOpen, setSearchOpen] = useState(false);
  const [query, setQuery] = useState("");
  const workspaceButtonRef = useRef<HTMLButtonElement>(null);
  const collapseButtonRef = useRef<HTMLButtonElement>(null);
  const expandButtonRef = useRef<HTMLButtonElement>(null);
  const searchButtonRef = useRef<HTMLButtonElement>(null);
  const searchRef = useRef<HTMLInputElement>(null);
  const workspaceMenuId = useId();

  const selectedTitle = activeTitle === undefined ? demoActiveTitle : activeTitle;
  const visibleRecents = recents.filter((item) =>
    item.label.toLowerCase().includes(query.trim().toLowerCase()),
  );

  const updateWorkspacePosition = useCallback(() => {
    const button = workspaceButtonRef.current;
    if (!button) return;
    const rect = button.getBoundingClientRect();
    const menuWidth = Math.min(256, window.innerWidth - 24);
    setWorkspacePosition({
      top: rect.bottom + 6,
      left: Math.max(12, Math.min(rect.left, window.innerWidth - menuWidth - 12)),
    });
  }, []);

  const openWorkspace = useCallback(() => {
    updateWorkspacePosition();
    setWorkspaceOpen(true);
  }, [updateWorkspacePosition]);

  const closeWorkspace = useCallback((restoreFocus = true) => {
    setWorkspaceOpen(false);
    if (restoreFocus) requestAnimationFrame(() => workspaceButtonRef.current?.focus());
  }, []);

  useEffect(() => {
    if (!workspaceOpen) return;
    const close = (event: PointerEvent) => {
      const target = event.target;
      if (
        target instanceof Element &&
        !target.closest("[data-workspace-trigger]") &&
        !target.closest("[data-workspace-menu]")
      ) {
        closeWorkspace(true);
      }
    };
    document.addEventListener("pointerdown", close);
    return () => document.removeEventListener("pointerdown", close);
  }, [closeWorkspace, workspaceOpen]);

  useEffect(() => {
    if (!workspaceOpen) return;
    window.addEventListener("resize", updateWorkspacePosition);
    window.addEventListener("scroll", updateWorkspacePosition, true);
    return () => {
      window.removeEventListener("resize", updateWorkspacePosition);
      window.removeEventListener("scroll", updateWorkspacePosition, true);
    };
  }, [updateWorkspacePosition, workspaceOpen]);

  useEffect(() => {
    if (searchOpen) searchRef.current?.focus();
  }, [searchOpen]);

  const closeSearch = (restoreFocus = true) => {
    setSearchOpen(false);
    setQuery("");
    if (restoreFocus) requestAnimationFrame(() => searchButtonRef.current?.focus());
  };

  const collapse = () => {
    setCollapsed(true);
    closeWorkspace(false);
    closeSearch(false);
    requestAnimationFrame(() => expandButtonRef.current?.focus());
  };

  const expand = () => {
    setCollapsed(false);
    requestAnimationFrame(() => collapseButtonRef.current?.focus());
  };

  return (
    <aside
      data-sidebar-collapsed={collapsed}
      aria-label="Workspace navigation"
      className={`relative flex shrink-0 overflow-hidden transition-[width] ${fill ? "h-full" : "h-[clamp(360px,75dvh,600px)]"} ${className}`}
      style={
        {
          width: collapsed ? SIDEBAR_MOTION.collapsedWidth : SIDEBAR_MOTION.expandedWidth,
          "--sidebar-expanded-width": SIDEBAR_MOTION.expandedWidth,
          transitionDuration: reducedMotion ? "0ms" : `${SIDEBAR_MOTION.duration}ms`,
          transitionTimingFunction: SIDEBAR_MOTION.easing,
          "--sidebar-copy-duration": reducedMotion ? "0ms" : `${SIDEBAR_MOTION.copyDuration}ms`,
          "--sidebar-copy-offset": `${SIDEBAR_MOTION.copyOffset}px`,
          "--sidebar-easing": SIDEBAR_MOTION.easing,
        } as CSSProperties
      }
    >
      <div className="flex min-h-0 w-[var(--sidebar-expanded-width)] shrink-0 flex-col">
        <div className="relative mb-2.5 h-10 shrink-0">
          <button
            ref={workspaceButtonRef}
            data-workspace-trigger
            type="button"
            aria-expanded={workspaceOpen}
            aria-haspopup="menu"
            aria-controls={workspaceOpen ? workspaceMenuId : undefined}
            aria-hidden={collapsed}
            tabIndex={collapsed ? -1 : 0}
            onClick={() => (workspaceOpen ? closeWorkspace(true) : openWorkspace())}
            onKeyDown={(event) => {
              if (!["Enter", " ", "ArrowDown"].includes(event.key)) return;
              event.preventDefault();
              if (event.key === "ArrowDown") {
                if (!workspaceOpen) openWorkspace();
                else
                  document
                    .getElementById(workspaceMenuId)
                    ?.querySelector<HTMLElement>("[role='menuitem']")
                    ?.focus();
                return;
              }
              if (workspaceOpen) closeWorkspace(true);
              else openWorkspace();
            }}
            className={`sidebar-workspace-control absolute left-2 top-1 flex h-8 w-[calc(var(--sidebar-expanded-width)-60px)] items-center ${shape.button} px-2 text-left transition-[background-color,transform] duration-80 hover:bg-[var(--hover-2)] active:scale-[0.98]`}
          >
            <span className="sidebar-logo flex size-5 shrink-0 items-center justify-center text-[var(--ink)]">
              <IconPopsicle2 size={18} />
            </span>
            <span className="sidebar-copy ml-1.5 min-w-0 flex-1 truncate text-[14px] font-medium text-[var(--ink-2)]">
              {WORKSPACE.name}
            </span>
            <span className="sidebar-copy ml-1 flex shrink-0 text-[var(--ink-3)]">
              <ChevronDownIcon size={16} />
            </span>
          </button>

          {workspaceOpen && (
            <WorkspaceMenu
              id={workspaceMenuId}
              position={workspacePosition}
              onClose={closeWorkspace}
            />
          )}

          <button
            ref={collapseButtonRef}
            type="button"
            aria-label="Collapse sidebar"
            aria-hidden={collapsed}
            tabIndex={collapsed ? -1 : 0}
            onClick={collapse}
            className={`sidebar-collapse-control absolute right-2 top-1 flex size-8 items-center justify-center ${shape.button} text-[var(--ink-3)] transition-[opacity,background-color,color,transform] duration-80 hover:bg-[var(--hover-2)] hover:text-[var(--ink)] active:scale-[0.98]`}
          >
            <ArrowLeftIcon size={18} />
          </button>
          <button
            ref={expandButtonRef}
            type="button"
            aria-label="Expand sidebar"
            aria-hidden={!collapsed}
            tabIndex={collapsed ? 0 : -1}
            onClick={expand}
            className={`sidebar-expand-control absolute left-2 top-0.5 flex size-9 items-center justify-center ${shape.button} text-[var(--ink-3)] transition-[opacity,background-color,color,transform] duration-80 hover:bg-[var(--hover-2)] hover:text-[var(--ink)] active:scale-[0.98]`}
          >
            <ArrowLeftIcon size={18} className="rotate-180" />
          </button>
        </div>

        <GlideGroup>
          <RailButton
            icon={<PencilIcon size={18} />}
            label="New chat"
            collapsed={collapsed}
            onClick={() => {
              if (activeTitle === undefined) setDemoActiveTitle(null);
              selectNav("chats");
              onNewChat?.();
            }}
          />
          {NAV_ITEMS.map((item) => (
            <RailButton
              key={item.key}
              icon={item.icon === "home" ? <HomeIcon size={18} /> : <UsersIcon size={18} />}
              label={item.label}
              count={item.count}
              active={currentNav === item.key}
              collapsed={collapsed}
              onClick={() => selectNav(item.key)}
            />
          ))}
        </GlideGroup>

        <div className="mt-3 min-h-0 flex-1 overflow-y-auto">
          <div className="sidebar-copy relative mx-2 mb-1 h-8">
            {!searchOpen ? (
              <>
                <div
                  aria-hidden={collapsed}
                  className="absolute inset-0 flex items-center gap-1.5 px-2 text-[13px] font-medium text-[var(--ink-3)]"
                >
                  <ChevronDownIcon size={16} />
                  <span>Chats</span>
                </div>

                <button
                  ref={searchButtonRef}
                  type="button"
                  aria-label="Search chats"
                  aria-hidden={collapsed}
                  tabIndex={collapsed ? -1 : 0}
                  onClick={() => setSearchOpen(true)}
                  className={`absolute right-0 top-0 z-10 flex size-8 items-center justify-center ${shape.button} text-[var(--ink-3)] transition-[background-color,color,transform] duration-80 hover:bg-[var(--hover-2)] hover:text-[var(--ink)] active:scale-[0.98]`}
                >
                  <SearchIcon size={16} />
                </button>
              </>
            ) : (
              <div
                data-bui-input-group=""
                className={`absolute right-0 top-0 z-20 flex h-8 w-full items-center overflow-hidden ${shape.input} bg-[var(--field)] text-[var(--ink-3)] shadow-[var(--shadow-hairline)] focus-within:text-[var(--ink-2)]`}
                style={{
                  animation: reducedMotion
                    ? "none"
                    : `fade-in ${CHAT_SEARCH_MOTION.duration}ms ${CHAT_SEARCH_MOTION.easing} both`,
                }}
              >
                <span className="ml-2 flex shrink-0 items-center justify-center">
                  <SearchIcon size={16} />
                </span>
                <input
                  ref={searchRef}
                  type="search"
                  value={query}
                  onChange={(event) => setQuery(event.target.value)}
                  onKeyDown={(event) => {
                    if (event.key === "Escape") closeSearch(true);
                  }}
                  placeholder="Search chats"
                  aria-label="Search chat history"
                  className="ml-1.5 min-w-0 flex-1 appearance-none rounded-none border-0 bg-transparent p-0 text-[13px] font-medium text-[var(--ink)] shadow-none outline-none placeholder:text-[var(--ink-3)] [&::-webkit-search-cancel-button]:hidden [&::-webkit-search-decoration]:hidden"
                />
                <button
                  type="button"
                  aria-label="Close chat search"
                  onClick={() => closeSearch(true)}
                  className={`flex size-8 shrink-0 items-center justify-center ${shape.button} text-[var(--ink-3)] transition-[background-color,color,transform] duration-80 hover:bg-[var(--hover-2)] hover:text-[var(--ink)] active:scale-[0.98]`}
                >
                  <CrossIcon size={16} />
                </button>
              </div>
            )}
          </div>

          <GlideGroup>
            {visibleRecents.map((item) => {
              const active = item.label === selectedTitle;
              return (
                <button
                  key={item.id}
                  data-row
                  type="button"
                  title={item.label}
                  aria-current={active ? "page" : undefined}
                  aria-hidden={collapsed}
                  tabIndex={collapsed ? -1 : 0}
                  onClick={() => {
                    selectNav("chats");
                    if (activeTitle === undefined) setDemoActiveTitle(item.label);
                    onPick?.(item.id, item.label, item.prompt);
                  }}
                  style={{
                    width: collapsed ? 36 : "calc(var(--sidebar-expanded-width) - 16px)",
                  }}
                  className={`sidebar-row relative z-10 mx-2 flex h-8 items-center ${shape.item} px-2 text-left transition-[width,background-color,color,transform] duration-80 active:scale-[0.98] ${
                    active
                      ? "bg-[var(--hover-2)] group-hover/glide:bg-transparent group-focus-within/glide:bg-transparent"
                      : ""
                  }`}
                >
                  <span
                    className={`sidebar-copy min-w-0 flex-1 truncate text-[14px] font-medium ${active ? "text-[var(--ink)]" : "text-[var(--ink-2)]"}`}
                  >
                    {item.label}
                  </span>
                </button>
              );
            })}
            {query && visibleRecents.length === 0 && (
              <div className="sidebar-copy mx-2 px-2 py-2 text-[12px] text-[var(--ink-3)]">
                No chats found
              </div>
            )}
          </GlideGroup>
        </div>

        <div className="sidebar-copy mx-2 mt-3 w-[calc(var(--sidebar-expanded-width)-16px)] border-t border-[var(--line)] pt-3">
          <button
            type="button"
            aria-hidden={collapsed}
            tabIndex={collapsed ? -1 : 0}
            onClick={onFooterClick ?? onNewChat}
            className={`flex h-8 w-full items-center justify-center gap-1.5 ${shape.button} bg-[var(--hover-2)] text-[13px] font-medium text-[var(--ink)] transition-[background-color,transform] duration-80 hover:bg-[var(--line-strong)] active:scale-[0.98]`}
          >
            {footerIcon}
            {footerLabel}
          </button>
        </div>
      </div>
    </aside>
  );
}

"use client";

import "./beautiful-ui.css";
import { forwardRef, type CSSProperties, type HTMLAttributes } from "react";
import { SurfaceProvider, useSurface } from "@/lib/surface-context";
import { useShapeVariant } from "@/lib/shape-context";

export type BeautifulUIRootProps = HTMLAttributes<HTMLDivElement>;

type AdapterStyle = CSSProperties & Record<`--${string}`, string | number>;

function clampSurface(level: number) {
  return Math.max(1, Math.min(8, level));
}

function createAdapterStyle(
  substrate: number,
  surface: number,
  style?: CSSProperties,
): AdapterStyle {
  const inset = clampSurface(substrate + 1);
  const overlay = clampSurface(surface + 2);
  const raisedOverlay = clampSurface(surface + 4);

  return {
    "--page": `var(--surface-${substrate})`,
    "--canvas": `var(--surface-${substrate})`,
    "--surface": `var(--surface-${surface})`,
    "--inset": `var(--surface-${inset})`,
    "--tooltip-bg": `var(--surface-${overlay})`,
    "--overlay-surface": `var(--surface-${overlay})`,
    "--overlay-raised": `var(--surface-${raisedOverlay})`,
    ...style,
  };
}

function useBeautifulUIScope(offset = 2) {
  const substrate = useSurface();
  const surface = clampSurface(substrate + offset);
  const shape = useShapeVariant();

  return {
    shape,
    substrate,
    surface,
    style: createAdapterStyle(substrate, surface),
  };
}

/**
 * Internal compatibility boundary for the adapted primitives. It has no layout
 * box of its own: public components use it internally so consumers inherit the
 * active BoringUI theme, surface level, and radius mode without a wrapper.
 */
export const BeautifulUIRoot = forwardRef<HTMLDivElement, BeautifulUIRootProps>(
  ({ className, style, ...props }, ref) => {
    const scope = useBeautifulUIScope();

    return (
      <SurfaceProvider value={scope.surface}>
        <div
          ref={ref}
          data-bui-component=""
          data-shape={scope.shape}
          data-surface={scope.surface}
